def operation(n):
    """Performs the operation: floor(n/10) + 3 * (n mod 10)"""
    return n // 10 + 3 * (n % 10)

def trace_sequence(start_n, steps=15):
    sequence = [start_n]
    current_n = start_n
    for i in range(1, steps + 1):
        current_n = operation(current_n)
        sequence.append(current_n)
    return sequence

start_values = [10, 26, 135, 20]
results = {}

for start in start_values:
    results[start] = trace_sequence(start)

# Print the results clearly
for start, seq in results.items():
    print(f"Start N = {start}: {seq}")

